import { COLLECTIONS } from '@modules/door-model/const';
import {
  useDoorCollection,
  useSetDoorCollection,
} from '@modules/door-model/store';
import { isCollectionGuard } from '@modules/door-model/util';
import dynamic from 'next/dynamic';
import { ChangeEvent, FC, useState } from 'react';
import { Select } from 'shared/Select';
import { OptionListTitle } from '../OptionListTitle';
import { EntireCollectionModal } from './EntireCollectionModal';

const Stars = dynamic<{ className?: string }>(
  () => import('public/assets/icons/stars.svg'),
);

export const Collection: FC = () => {
  const collection = useDoorCollection();
  const setDoorCollection = useSetDoorCollection();
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleCollectionChange = ({
    currentTarget: { value },
  }: ChangeEvent<HTMLSelectElement>) => {
    if (!isCollectionGuard(value)) return;
    const collection =
      COLLECTIONS.find((item) => item.name === value) || COLLECTIONS[0];
    setDoorCollection(collection);
  };
  return (
    <>
      <div className="flex md:flex-col lg:flex-row justify-between gap-8 lg:gap-40">
        <OptionListTitle title="Layout" value={collection.name} />
        <button
          className="flex gap-8 items-center text-tiny mb-12 md:mb-12"
          onClick={() => setIsModalOpen(true)}>
          View entire collection <Stars />
        </button>
      </div>
      <Select
        id="collection"
        name="status"
        onChange={handleCollectionChange}
        value={collection.name}
        className="w-full mb-40"
        options={COLLECTIONS.map((item) => ({
          name: item.name || '',
          value: item.name || '',
        }))}
      />
      <EntireCollectionModal isOpen={isModalOpen} setIsOpen={setIsModalOpen} />
    </>
  );
};

