const targetScaleY = resolvedHeight / sourceHeight;

// Scale the -V (front) mesh to match the -U (back) mesh dimensions first.
const vScale = useMemo(() => {
  const { scaleX, scaleY, vCenter, uCenter } = computeVScaleFactors(
    nodes,
    size,
    designId,
  );
  return { scaleX, scaleY, vCenter, uCenter };
}, [nodes, size, designId]);

const [vKey, uKey] = meshKeys(designId, size);
const [vIntKey, uIntKey] = intMeshKeys(designId, size);
const vIntMesh = nodes[vIntKey] ?? null;
const uIntMesh = nodes[uIntKey] ?? null;
const halfTargetWidth = resolvedWidth / 2;
const halfTargetHeight = resolvedHeight / 2;

const clippingPlanes = useMemo(() => {
  // Keep panel clipped to requested width/height around its own center.
  const left = panelX - halfTargetWidth;
  const right = panelX + halfTargetWidth;
  const bottom = panelY - halfTargetHeight;
  const top = panelY + halfTargetHeight;

  const wallHalfDepth = WALL_THICKNESS / 2;
  const wallFrontZ = WALL_CENTER_Z + wallHalfDepth;
  const wallBackZ = WALL_CENTER_Z - wallHalfDepth;

  return [
    new THREE.Plane(new THREE.Vector3(1, 0, 0), -left),
    new THREE.Plane(new THREE.Vector3(-1, 0, 0), right),
    new THREE.Plane(new THREE.Vector3(0, 1, 0), -bottom),
    new THREE.Plane(new THREE.Vector3(0, -1, 0), top),
    new THREE.Plane(new THREE.Vector3(0, 0, 1), -wallBackZ),
    new THREE.Plane(new THREE.Vector3(0, 0, -1), wallFrontZ),
  ];
}, [halfTargetHeight, halfTargetWidth, panelX, panelY]);

const clippedMaterial = useMemo(() => {
  const base = ralMaterial ?? materials.Boja1;
  const material = base.clone();
  material.clippingPlanes = clippingPlanes;
  material.clipShadows = true;
  material.needsUpdate = true;
  return material;
}, [clippingPlanes, ralMaterial, materials.Boja1]);

useEffect(() => {
  return () => {
    clippedMaterial.dispose();
  };
}, [clippedMaterial]);

const clippedIntMaterial = useMemo(() => {
  const intNode = vIntMesh ?? uIntMesh;
  if (!intNode) return null;
  const base = Array.isArray(intNode.material)
    ? intNode.material[0]
    : intNode.material;
  const material = (base as THREE.MeshStandardMaterial).clone();
  material.clippingPlanes = clippingPlanes;
  material.clipShadows = true;
  material.needsUpdate = true;
  return material;
}, [clippingPlanes, vIntMesh, uIntMesh]);

useEffect(() => {
  return () => {
    clippedIntMaterial?.dispose();
  };
}, [clippedIntMaterial]);

return (
  <group position={position} scale={[mirrored ? -1 : 1, 1, 1]} dispose={null}>
    {/* Offset so the geometric center sits at origin */}
    <group
      position={[-centerOffset.x, -centerOffset.y, -centerOffset.z]}
      scale={[targetScaleX, targetScaleY, 1]}>
      {/* Front panel (-V) — scaled to match back panel dimensions, pivoting from its center */}
      <group
        position={[
          vScale.vCenter.x,
          vScale.vCenter.y,
          vScale.vCenter.z - 0.01,
        ]}>
        <group scale={[vScale.scaleX, vScale.scaleY, 1]}>
          <mesh
            castShadow
            receiveShadow
            geometry={nodes[vKey].geometry}
            material={clippedMaterial}
            position={[
