import {
  WALL_CENTER_Z,
  WALL_THICKNESS,
} from '@modules/door-model/components/parametric/ParametricWall';
import { useDoorMaterial } from '@modules/door-model/hooks/useDoorMaterials';
import { useGLTF } from '@react-three/drei';
import { FC, useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { GLTF } from 'three-stdlib';

type GLTFResult = GLTF & {
  nodes: Record<string, THREE.Mesh>;
  materials: {
    Boja1: THREE.MeshStandardMaterial;
  };
};

// ── Size definitions ──────────────────────────────────────────────────────────
export type DoorPanelSize = 'L' | 'M' | 'S';

/** Returns the V (front) and U (back) node keys for a given design and size. */
function meshKeys(designId: string, size: DoorPanelSize): [string, string] {
  const id = designId.toUpperCase();
  return [`${id}-${size}-V-P1`, `${id}-${size}-U-P1`];
}

/** Returns the V-int (front) and U-int (back) interior node keys for a given design and size. */
function intMeshKeys(designId: string, size: DoorPanelSize): [string, string] {
  const id = designId.toUpperCase();
  return [`${id}-${size}-V-int`, `${id}-${size}-U-int`];
}

// ── Bounding-box helpers ──────────────────────────────────────────────────────
export interface DoorPanelBounds {
  /** Panel width in meters (X extent) */
  width: number;
  /** Panel height in meters (Y extent) */
  height: number;
  /** Panel depth/thickness in meters (Z extent) */
  depth: number;
}

/** Compute bounding box for a single mesh. */
function computeSingleMeshBounds(mesh: THREE.Mesh) {
  const box = new THREE.Box3();
  if (mesh?.geometry) {
    mesh.geometry.computeBoundingBox();
    if (mesh.geometry.boundingBox) {
      box.copy(mesh.geometry.boundingBox);
    }
  }
  const sizeVec = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(sizeVec);
  box.getCenter(center);
  return { box, sizeVec, center };
}

/** Compute combined bounding box for both meshes of a size variant. */
function computeBoundsForSize(
  nodes: GLTFResult['nodes'],
  size: DoorPanelSize,
  designId: string,
) {
  const box = new THREE.Box3();
  const [key1, key2] = meshKeys(designId, size);

  [nodes[key1], nodes[key2]].forEach((mesh) => {
    if (mesh?.geometry) {
      mesh.geometry.computeBoundingBox();
      if (mesh.geometry.boundingBox) {
        box.union(mesh.geometry.boundingBox);
      }
    }
  });

  const sizeVec = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(sizeVec);
  box.getCenter(center);

  return { sizeVec, center };
}

/**
 * Compute the scale factors needed to make the -V (front) mesh
 * match the -U (back) mesh dimensions.
 * The -V meshes are ~50mm smaller in width and height across all sizes.
 */
function computeVScaleFactors(
  nodes: GLTFResult['nodes'],
  size: DoorPanelSize,
  designId: string,
) {
  const [vKey, uKey] = meshKeys(designId, size);
  const vBounds = computeSingleMeshBounds(nodes[vKey]);
  const uBounds = computeSingleMeshBounds(nodes[uKey]);

  return {
    scaleX: vBounds.sizeVec.x > 0 ? uBounds.sizeVec.x / vBounds.sizeVec.x : 1,
    scaleY: vBounds.sizeVec.y > 0 ? uBounds.sizeVec.y / vBounds.sizeVec.y : 1,
    // Keep Z (depth) at 1 — both panels are the same thickness
    vCenter: vBounds.center,
    uCenter: uBounds.center,
  };
}

/**
 * Returns the bounding-box dimensions (in meters) of the door panel model
 * for the given size variant.
 *
 * The model is already in meters (exported via Blender glTF I/O).
 * Cached via useGLTF internally — safe to call from multiple components.
 */
export function useDoorPanelBounds(
  modelSrc: string,
  designId: string,
  size: DoorPanelSize = 'L',
): DoorPanelBounds {
  const { nodes } = useGLTF(modelSrc) as unknown as GLTFResult;

  return useMemo(() => {
    const { sizeVec } = computeBoundsForSize(nodes, size, designId);
    return {
      width: sizeVec.x,
      height: sizeVec.y,
      depth: sizeVec.z,
    };
  }, [nodes, size, designId]);
}

// ── Component ─────────────────────────────────────────────────────────────────
interface DoorPanelProps {
  modelSrc: string;
  designId: string;
  size?: DoorPanelSize;
  targetWidth?: number;
  targetHeight?: number;
  materialId?: string;
  position?: [number, number, number];
  mirrored?: boolean;
}

/**
 * Renders the door panel 3D model for the selected design and size.
 * The model is auto-centered at the group's origin so frame / glass / wall
 * can be positioned relative to its geometric center.
 */
export const DoorPanel: FC<DoorPanelProps> = ({
  modelSrc,
  designId,
  size = 'L',
  targetWidth,
  targetHeight,
  materialId,
  position = [0, 0, 0],
  mirrored = false,
}) => {
  const { nodes, materials } = useGLTF(modelSrc) as unknown as GLTFResult;
  const ralMaterial = useDoorMaterial(materialId);
  const [panelX, panelY] = position;

  const panelBounds = useMemo(() => {
    return computeBoundsForSize(nodes, size, designId);
  }, [nodes, size, designId]);

  const centerOffset = panelBounds.center;
  const sourceWidth = panelBounds.sizeVec.x || 1;
  const sourceHeight = panelBounds.sizeVec.y || 1;
  const resolvedWidth = targetWidth ?? sourceWidth;
  const resolvedHeight = targetHeight ?? sourceHeight;

  // Scale the selected source model to requested target dimensions.
  const targetScaleX = resolvedWidth / sourceWidth;
  const targetScaleY = resolvedHeight / sourceHeight;

  // Scale the -V (front) mesh to match the -U (back) mesh dimensions first.
  const vScale = useMemo(() => {
    const { scaleX, scaleY, vCenter, uCenter } = computeVScaleFactors(
      nodes,
      size,
      designId,
    );
    return { scaleX, scaleY, vCenter, uCenter };
  }, [nodes, size, designId]);

  const [vKey, uKey] = meshKeys(designId, size);
  const [vIntKey, uIntKey] = intMeshKeys(designId, size);
  const vIntMesh = nodes[vIntKey] ?? null;
  const uIntMesh = nodes[uIntKey] ?? null;
  const halfTargetWidth = resolvedWidth / 2;
  const halfTargetHeight = resolvedHeight / 2;

  const clippingPlanes = useMemo(() => {
    // Keep panel clipped to requested width/height around its own center.
    const left = panelX - halfTargetWidth;
    const right = panelX + halfTargetWidth;
    const bottom = panelY - halfTargetHeight;
    const top = panelY + halfTargetHeight;

    const wallHalfDepth = WALL_THICKNESS / 2;
    const wallFrontZ = WALL_CENTER_Z + wallHalfDepth;
    const wallBackZ = WALL_CENTER_Z - wallHalfDepth;

    return [
      new THREE.Plane(new THREE.Vector3(1, 0, 0), -left),
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), right),
      new THREE.Plane(new THREE.Vector3(0, 1, 0), -bottom),
      new THREE.Plane(new THREE.Vector3(0, -1, 0), top),
      new THREE.Plane(new THREE.Vector3(0, 0, 1), -wallBackZ),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), wallFrontZ),
    ];
  }, [halfTargetHeight, halfTargetWidth, panelX, panelY]);

  const clippedMaterial = useMemo(() => {
    const base = ralMaterial ?? materials.Boja1;
    const material = base.clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, ralMaterial, materials.Boja1]);

  useEffect(() => {
    return () => {
      clippedMaterial.dispose();
    };
  }, [clippedMaterial]);

  const clippedIntMaterial = useMemo(() => {
    const intNode = vIntMesh ?? uIntMesh;
    if (!intNode) return null;
    const base = Array.isArray(intNode.material)
      ? intNode.material[0]
      : intNode.material;
    const material = (base as THREE.MeshStandardMaterial).clone();
    material.clippingPlanes = clippingPlanes;
    material.clipShadows = true;
    material.needsUpdate = true;
    return material;
  }, [clippingPlanes, vIntMesh, uIntMesh]);

  useEffect(() => {
    return () => {
      clippedIntMaterial?.dispose();
    };
  }, [clippedIntMaterial]);

  return (
    <group position={position} scale={[mirrored ? -1 : 1, 1, 1]} dispose={null}>
      {/* Offset so the geometric center sits at origin */}
      <group
        position={[-centerOffset.x, -centerOffset.y, -centerOffset.z]}
        scale={[targetScaleX, targetScaleY, 1]}>
        {/* Front panel (-V) — scaled to match back panel dimensions, pivoting from its center */}
        <group
          position={[
            vScale.vCenter.x,
            vScale.vCenter.y,
            vScale.vCenter.z - 0.01,
          ]}>
          <group scale={[vScale.scaleX, vScale.scaleY, 1]}>
            <mesh
              castShadow
              receiveShadow
              geometry={nodes[vKey].geometry}
              material={clippedMaterial}
              position={[
                -vScale.vCenter.x,
                -vScale.vCenter.y,
                -vScale.vCenter.z,
              ]}
            />
            {vIntMesh && clippedIntMaterial && (
              <mesh
                receiveShadow
                geometry={vIntMesh.geometry}
                material={clippedIntMaterial}
                position={[
                  -vScale.vCenter.x,
                  -vScale.vCenter.y,
                  -vScale.vCenter.z,
                ]}
              />
            )}
          </group>
        </group>

        {/* Back panel (-U) — fits perfectly, no scaling needed */}
        <mesh
          castShadow
          receiveShadow
          geometry={nodes[uKey].geometry}
          material={clippedMaterial}
        />
        {uIntMesh && clippedIntMaterial && (
          <mesh
            receiveShadow
            geometry={uIntMesh.geometry}
            material={clippedIntMaterial}
          />
        )}
      </group>
    </group>
  );
};

