/**
 * Fallback: scans all nodes for a staklo mesh matching the given size and side.
 * Handles GLBs where staklo nodes were exported with a different design ID prefix.
 */
function findStakloNode(
  nodes: Record<string, THREE.Mesh>,
  size: DoorPanelSize,
  side: 'V' | 'U',
): THREE.Mesh | null {
  const suffix = `-${size}-${side}-staklo`;
  const entry = Object.entries(nodes).find(([key]) => key.endsWith(suffix));
  return entry ? (entry[1] as THREE.Mesh) : null;
}

