  side: 'V' | 'U',
): THREE.Mesh | null {
  const suffix = `-${size}-${side}-staklo`;
  const entry = Object.entries(nodes).find(([key]) => key.endsWith(suffix));
  return entry ? (entry[1] as THREE.Mesh) : null;
}
